#!/usr/bin/env python3
# derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4
"""Compile a scenario to a TLC run and print PASS, FAIL <clause>, or UNEXPLAINED <reason>."""

import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MODEL = ROOT / "model"
JAR = Path.home() / "projects" / "tlaplus" / "tla2tools.jar"
OBSERVE = MODEL / "observe"
SCENARIO_DIR = ROOT / "replay" / "scenarios"

MEMBERS = ("m1", "m2", "m3", "m4", "m5")
SELECTORS = ("coordinator", "follower", "crashed")
# A completing path of every shared scenario needs two elections. One further
# campaign is left so a split vote can retry. Measured election skeleton at
# this epoch cap was about two million states.
MAX_EPOCH = 3
# S8 appends three configuration entries. One spare slot.
MAX_LOG = 4
# One successful catch-up extend, plus retries after a lost reply.
MAX_ROUNDS = 3
# Explore fault counts: no shared scenario exceeds these, and each scenario's
# own faults fit (S8 has three admin steps; S6's cut is four undirected pairs).
EXPLORE_CRASHES = 1
EXPLORE_ADMIN = 3
EXPLORE_LINKS = 4
EXPLORE_EVENTS = 400

MUTATIONS = {
    "S1": "double_vote",
    "S2": "double_vote",
    "S3": "double_vote",
    "S4": "skip_uptodate",
    "S5": "skip_uptodate",
    "S6": "skip_uptodate",
    "S7": "skip_uptodate",
    "S8": "wide_change",
}
CLAUSE = {"J11": "J1.1", "J13": "J1.3", "J15": "J1.5"}
TRIGGER_FIELDS = {"event", "member", "index", "kind", "status", "epoch", "op", "target"}


class ScenarioError(Exception):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


def outcome_line(reason_or_line):
    print(reason_or_line, flush=True)


# ---------- YAML subset ----------

def _strip_comment(line):
    out = []
    quote = False
    esc = False
    for ch in line:
        if quote:
            out.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
            out.append(ch)
        elif ch == "#":
            break
        else:
            out.append(ch)
    return "".join(out).rstrip()


def _flow_depth(text):
    depth = 0
    quote = False
    esc = False
    for ch in text:
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch in "{[":
            depth += 1
        elif ch in "}]":
            depth -= 1
    return depth


def _logical_lines(text):
    raw = []
    for n, line in enumerate(text.splitlines(), 1):
        if line.startswith("---") and n == 1:
            continue
        code = _strip_comment(line)
        if code.strip() == "":
            continue
        if code[:1] == "\t" or "\t" in code[: len(code) - len(code.lstrip(" \t"))]:
            raise ScenarioError("scenario: tab indent")
        indent = len(code) - len(code.lstrip(" "))
        raw.append([indent, code.strip(), n])
    lines = []
    buf = None
    for indent, text, n in raw:
        if buf is None:
            if _flow_depth(text) > 0:
                buf = [indent, text, n]
            else:
                lines.append((indent, text, n))
        else:
            buf[1] += " " + text
            if _flow_depth(buf[1]) <= 0:
                lines.append((buf[0], buf[1], buf[2]))
                buf = None
    if buf is not None:
        raise ScenarioError("scenario: unclosed flow")
    return lines


def _split_key(text):
    quote = False
    esc = False
    for i, ch in enumerate(text):
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch == ":":
            key = text[:i].strip()
            rest = text[i + 1 :].strip()
            if key == "":
                raise ScenarioError("scenario: empty key")
            return key, rest
    raise ScenarioError("scenario: expected key")


class _Flow:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in " \t\r\n":
            self.i += 1

    def parse(self):
        self.skip()
        if self.i >= len(self.s):
            raise ScenarioError("scenario: truncated flow")
        ch = self.s[self.i]
        if ch == "{":
            return self.mapping()
        if ch == "[":
            return self.seq()
        if ch == '"':
            return self.string()
        return self.scalar()

    def mapping(self):
        self.i += 1
        out = {}
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            key = self.key()
            self.skip()
            if self.i >= len(self.s) or self.s[self.i] != ":":
                raise ScenarioError("scenario: flow key")
            self.i += 1
            out[key] = self.parse()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow mapping")

    def key(self):
        self.skip()
        if self.i < len(self.s) and self.s[self.i] == '"':
            return self.string()
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ":},[]":
            self.i += 1
        key = self.s[start:self.i].strip()
        if key == "":
            raise ScenarioError("scenario: empty flow key")
        return key

    def seq(self):
        self.i += 1
        out = []
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow list")

    def string(self):
        self.i += 1
        chars = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == "\\":
                if self.i >= len(self.s):
                    raise ScenarioError("scenario: bad string")
                nxt = self.s[self.i]
                self.i += 1
                chars.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(nxt, nxt))
            elif ch == '"':
                return "".join(chars)
            else:
                chars.append(ch)
        raise ScenarioError("scenario: unclosed string")

    def scalar(self):
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ",}]":
            self.i += 1
        word = self.s[start:self.i].strip()
        if word == "":
            raise ScenarioError("scenario: empty scalar")
        return _scalar(word)


def _scalar(word):
    if word == "true":
        return True
    if word == "false":
        return False
    if word == "null":
        return None
    if re.fullmatch(r"-?\d+", word):
        return int(word)
    return word


def _parse_flow(text):
    parser = _Flow(text)
    value = parser.parse()
    parser.skip()
    if parser.i != len(parser.s):
        raise ScenarioError("scenario: trailing flow")
    return value


class _Doc:
    def __init__(self, lines):
        self.lines = lines
        self.k = 0

    def parse(self):
        if not self.lines:
            raise ScenarioError("scenario: empty file")
        return self._block(0)

    def _block(self, indent):
        if self.k >= len(self.lines):
            return None
        ind, text, _n = self.lines[self.k]
        if ind < indent:
            return None
        if text.startswith("- ") or text == "-":
            return self._list(ind)
        return self._dict(ind)

    def _dict(self, indent):
        out = {}
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind < indent:
                break
            if ind > indent or text.startswith("- ") or text == "-":
                break
            key, rest = _split_key(text)
            if key in out:
                raise ScenarioError(f"scenario: duplicate key {key}")
            self.k += 1
            out[key] = self._value(indent, rest, n)
        return out

    def _list(self, indent):
        items = []
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind != indent or not (text.startswith("- ") or text == "-"):
                break
            rest = text[1:].strip()
            self.k += 1
            if rest == "":
                items.append(self._block(indent + 1))
            elif rest.startswith("{") or rest.startswith("["):
                items.append(_parse_flow(rest))
            elif ":" in rest.split(" ")[0] or (":" in rest and not rest.startswith('"')):
                key, rval = _split_key(rest)
                item = {key: self._value(indent, rval, n)}
                while self.k < len(self.lines):
                    ind2, text2, n2 = self.lines[self.k]
                    if ind2 <= indent or text2.startswith("- ") or text2 == "-":
                        break
                    key2, rest2 = _split_key(text2)
                    self.k += 1
                    item[key2] = self._value(ind2, rest2, n2)
                items.append(item)
            else:
                items.append(_scalar(rest) if not rest.startswith('"') else _parse_flow(rest))
        return items

    def _value(self, indent, rest, _n):
        if rest == "":
            return self._block(indent + 1)
        if rest.startswith("{") or rest.startswith("["):
            return _parse_flow(rest)
        if rest.startswith('"'):
            return _parse_flow(rest)
        return _scalar(rest)


def load_scenario(path):
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        raise ScenarioError(f"scenario file not found") from exc
    doc = _Doc(_logical_lines(text)).parse()
    if not isinstance(doc, dict):
        raise ScenarioError("scenario: expected a mapping")
    return doc


# ---------- scenario to TLA ----------

def _name(value, what):
    if not isinstance(value, str) or value == "":
        raise ScenarioError(f"scenario: {what} needs a member")
    if value not in MEMBERS and value not in SELECTORS:
        raise ScenarioError(f"member {value}")
    return value


def _trigger(at):
    blank = {
        "kind": "event",
        "event": "",
        "member": "",
        "index": -1,
        "ekind": "",
        "status": "",
        "epoch": -1,
        "op": "",
        "target": "",
    }
    if at == "start":
        blank["kind"] = "start"
        return blank
    if not isinstance(at, dict) or "event" not in at:
        raise ScenarioError("scenario: trigger")
    extra = set(at) - TRIGGER_FIELDS
    if extra:
        raise ScenarioError("trigger field " + sorted(extra)[0])
    blank["event"] = str(at["event"])
    if "member" in at:
        blank["member"] = _name(str(at["member"]), "trigger member")
    if "index" in at:
        if not isinstance(at["index"], int):
            raise ScenarioError("scenario: index")
        blank["index"] = at["index"]
    if "kind" in at:
        blank["ekind"] = str(at["kind"])
    if "status" in at:
        blank["status"] = str(at["status"])
    if "epoch" in at:
        if not isinstance(at["epoch"], int):
            raise ScenarioError("scenario: epoch filter")
        blank["epoch"] = at["epoch"]
    if "op" in at:
        blank["op"] = str(at["op"])
    if "target" in at:
        blank["target"] = _name(str(at["target"]), "trigger target")
    return blank


def _action(do):
    if not isinstance(do, dict):
        raise ScenarioError("scenario: action")
    keys = [k for k in do.keys() if k != "at"]
    if len(keys) != 1:
        raise ScenarioError("scenario: action")
    kind = keys[0]
    base = {"kind": kind, "at": "", "target": "", "cmd": "", "links": []}
    if kind in ("add", "remove"):
        base["target"] = _name(str(do[kind]), kind)
        if "at" not in do:
            raise ScenarioError(f"scenario: {kind} needs at")
        base["at"] = _name(str(do["at"]), kind)
    elif kind in ("crash", "restart"):
        base["target"] = _name(str(do[kind]), kind)
    elif kind == "command":
        if not isinstance(do["command"], str) or do["command"] == "":
            raise ScenarioError("scenario: command")
        if "at" not in do:
            raise ScenarioError("scenario: command needs at")
        base["cmd"] = do["command"]
        base["at"] = _name(str(do["at"]), "command")
    elif kind in ("cut", "drop"):
        pairs = do[kind]
        if not isinstance(pairs, list):
            raise ScenarioError(f"scenario: {kind}")
        links = []
        for pair in pairs:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ScenarioError(f"scenario: {kind} pair")
            links.append((_name(str(pair[0]), kind), _name(str(pair[1]), kind)))
        base["links"] = links
    elif kind == "heal":
        pass
    else:
        raise ScenarioError(f"scenario: unknown action {kind}")
    return base


def _uses(action, name):
    if action["at"] == name or action["target"] == name:
        return True
    return any(a == name or b == name for a, b in action["links"])


def normalize(doc):
    if "initial" not in doc or not isinstance(doc["initial"], list) or not doc["initial"]:
        raise ScenarioError("scenario: missing initial")
    initial = []
    for member in doc["initial"]:
        if str(member) not in MEMBERS:
            raise ScenarioError(f"member {member}")
        if str(member) not in initial:
            initial.append(str(member))
    end = doc.get("end")
    bound = doc.get("bound")
    if not isinstance(end, dict) or not isinstance(end.get("settle"), int) or end["settle"] < 0:
        raise ScenarioError("scenario: missing end")
    if not isinstance(bound, dict) or not isinstance(bound.get("events"), int) or bound["events"] < 1:
        raise ScenarioError("scenario: missing bound")
    steps_in = doc.get("steps", [])
    if steps_in is None:
        steps_in = []
    if not isinstance(steps_in, list):
        raise ScenarioError("scenario: steps")
    steps = []
    seen_crash = False
    for raw in steps_in:
        if not isinstance(raw, dict) or "at" not in raw or "do" not in raw:
            raise ScenarioError("scenario: step")
        trig = _trigger(raw["at"])
        act = _action(raw["do"])
        if _uses(act, "crashed") and not seen_crash:
            raise ScenarioError("selector crashed before any crash")
        if trig["kind"] == "start" and _uses(act, "coordinator") and not steps:
            raise ScenarioError("selector coordinator before any election")
        steps.append({"trigger": trig, "action": act})
        if act["kind"] == "crash":
            seen_crash = True
    name = doc.get("scenario", "")
    if not isinstance(name, str):
        name = str(name)
    return {
        "name": name,
        "initial": initial,
        "settle": end["settle"],
        "events": bound["events"],
        "steps": steps,
    }


def tla_str(text):
    esc = text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{esc}"'


def tla_set(items):
    if not items:
        return "{}"
    return "{" + ", ".join(tla_str(x) for x in items) + "}"


def _trig_tla(trig):
    fields = [
        ("kind", tla_str(trig["kind"])),
        ("event", tla_str(trig["event"])),
        ("member", tla_str(trig["member"])),
        ("index", str(trig["index"])),
        ("ekind", tla_str(trig["ekind"])),
        ("status", tla_str(trig["status"])),
        ("epoch", str(trig["epoch"])),
        ("op", tla_str(trig["op"])),
        ("target", tla_str(trig["target"])),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def _act_tla(act):
    if act["links"]:
        body = ", ".join(
            f"<<{tla_str(a)}, {tla_str(b)}>>" for a, b in act["links"]
        )
        links = f"<< {body} >>"
    else:
        links = "<< >>"
    fields = [
        ("kind", tla_str(act["kind"])),
        ("at", tla_str(act["at"])),
        ("target", tla_str(act["target"])),
        ("cmd", tla_str(act["cmd"])),
        ("links", links),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def mc_text(spec, mutation, explore):
    if spec["steps"]:
        parts = []
        for step in spec["steps"]:
            parts.append(
                "  [trigger |->\n" + _trig_tla(step["trigger"])
                + ",\n   action |->\n" + _act_tla(step["action"]) + "]"
            )
        steps = "<<\n" + ",\n".join(parts) + "\n>>"
    else:
        steps = "<< >>"
    crashes = EXPLORE_CRASHES if explore else 0
    admin = EXPLORE_ADMIN if explore else 0
    links = EXPLORE_LINKS if explore else 0
    events = EXPLORE_EVENTS if explore else spec["events"]
    settle = 0 if explore else spec["settle"]
    lines = [
        "---- MODULE MC ----",
        "\\* derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4",
        "EXTENDS Journal",
        "",
        "InitCfg == " + tla_set(spec["initial"]),
        f"MaxEpochC == {MAX_EPOCH}",
        f"MaxLogLenC == {MAX_LOG}",
        f"MaxRoundsC == {MAX_ROUNDS}",
        f"SettleC == {settle}",
        f"MaxEventsC == {events}",
        "MutationC == " + tla_str(mutation),
        "ExploreC == " + ("TRUE" if explore else "FALSE"),
        f"MaxCrashesC == {crashes}",
        f"MaxAdminC == {admin}",
        f"MaxLinkC == {links}",
        'CommandsC == {"c1"}',
        "StepsC == " + steps,
        "====",
        "",
    ]
    return "\n".join(lines)


CFG = """\
SPECIFICATION Spec
INVARIANT J11
INVARIANT J13
INVARIANT J15
CONSTRAINT StateConstraint
CONSTANTS
  InitialConfig <- InitCfg
  MaxEpoch <- MaxEpochC
  MaxLogLen <- MaxLogLenC
  MaxRounds <- MaxRoundsC
  SettleN <- SettleC
  MaxEvents <- MaxEventsC
  Mutation <- MutationC
  Explore <- ExploreC
  MaxCrashes <- MaxCrashesC
  MaxAdmin <- MaxAdminC
  MaxLinkFaults <- MaxLinkC
  Commands <- CommandsC
  Steps <- StepsC
"""


# ---------- TLC values ----------

class _Tla:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in " \t\r\n":
            self.i += 1

    def parse(self):
        self.skip()
        if self.i >= len(self.s):
            raise ValueError("truncated TLA value")
        if self.s.startswith("<<", self.i):
            return self.sequence()
        ch = self.s[self.i]
        if ch == "{":
            return self.set_()
        if ch == "[":
            return self.record()
        if ch == '"':
            return self.string()
        if ch == "-" or ch.isdigit():
            return self.number()
        if ch.isalpha() or ch == "_":
            return self.word()
        raise ValueError("bad TLA value at " + self.s[self.i : self.i + 20])

    def sequence(self):
        self.i += 2
        out = []
        while True:
            self.skip()
            if self.s.startswith(">>", self.i):
                self.i += 2
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def set_(self):
        self.i += 1
        out = []
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def record(self):
        self.i += 1
        out = {}
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            key = self.word() if self.s[self.i].isalpha() or self.s[self.i] == "_" else self.string()
            self.skip()
            if not self.s.startswith("|->", self.i):
                raise ValueError("expected |->")
            self.i += 3
            out[key] = self.parse()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def string(self):
        self.i += 1
        chars = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == "\\":
                if self.i >= len(self.s):
                    raise ValueError("bad string")
                nxt = self.s[self.i]
                self.i += 1
                chars.append('"' if nxt == '"' else nxt)
            elif ch == '"':
                return "".join(chars)
            else:
                chars.append(ch)
        raise ValueError("unclosed string")

    def number(self):
        start = self.i
        if self.s[self.i] == "-":
            self.i += 1
        while self.i < len(self.s) and self.s[self.i].isdigit():
            self.i += 1
        return int(self.s[start:self.i])

    def word(self):
        start = self.i
        while self.i < len(self.s) and (self.s[self.i].isalnum() or self.s[self.i] == "_"):
            self.i += 1
        word = self.s[start:self.i]
        if word == "TRUE":
            return True
        if word == "FALSE":
            return False
        return word


def parse_tla(text):
    parser = _Tla(text)
    value = parser.parse()
    return value


def trace_events(log):
    marker = "The behavior up to this point is:"
    start = log.find(marker)
    if start < 0:
        return None
    body = log[start:]
    heads = list(re.finditer(r"(?m)^State \d+:.*$", body))
    if not heads:
        return None
    events = []
    for i, head in enumerate(heads):
        end = heads[i + 1].start() if i + 1 < len(heads) else len(body)
        chunk = body[head.end():end]
        found = re.search(r"(?m)^/\\ obs =[ \t]*", chunk)
        if not found:
            continue
        try:
            obs = parse_tla(chunk[found.end():])
        except ValueError as exc:
            raise ScenarioError(f"trace parse: {exc}") from exc
        if isinstance(obs, list):
            events.extend(obs)
    return events


def event_json(ev, run):
    name = ev.get("event", "")
    row = {
        "proc": ev.get("proc", ""),
        "seq": ev.get("seq", 0),
        "event": name,
        "causes": [],
        "run": run,
        "side": "model",
    }
    for cause in ev.get("causes") or []:
        if isinstance(cause, dict):
            row["causes"].append({"proc": cause.get("proc", ""), "seq": cause.get("seq", 0)})
    conf = ev.get("conf") or []
    if isinstance(conf, list):
        conf = sorted(str(x) for x in conf)
    if name == "Elected":
        row["epoch"] = ev.get("epoch", 0)
        row["config"] = conf
    elif name == "Appended":
        row["index"] = ev.get("index", 0)
        row["epoch"] = ev.get("epoch", 0)
        row["kind"] = ev.get("kind", "")
        row["payload"] = conf if ev.get("kind") == "config" else ev.get("cmd", "")
    elif name == "Truncated":
        row["from_index"] = ev.get("from", 0)
    elif name == "Committed":
        row["index"] = ev.get("index", 0)
        row["epoch"] = ev.get("epoch", 0)
    elif name == "ConfigInEffect":
        row["index"] = ev.get("index", 0)
        row["config"] = conf
    elif name == "ChangeRequested":
        row["op"] = ev.get("op", "")
        row["target"] = ev.get("target", "")
    elif name == "ChangeReplied":
        row["op"] = ev.get("op", "")
        row["target"] = ev.get("target", "")
        row["status"] = ev.get("status", "")
    elif name == "Fault":
        row["action"] = ev.get("op", "")
        if ev.get("op") in ("cut", "drop"):
            links = []
            for link in ev.get("links") or []:
                if isinstance(link, list) and len(link) == 2:
                    links.append([str(link[0]), str(link[1])])
            row["links"] = sorted(links)
    return row


def write_observe(events, run):
    OBSERVE.mkdir(parents=True, exist_ok=True)
    path = OBSERVE / f"{run}.jsonl"
    lines = [json.dumps(event_json(ev, run), separators=(",", ":"), sort_keys=False) for ev in events]
    path.write_text("\n".join(lines) + ("\n" if lines else ""), encoding="utf-8")
    return path


# ---------- TLC ----------

def _fingerprint_miss(log):
    vals = []
    for raw in re.findall(r"val = ([0-9.eE+-]+)", log):
        try:
            vals.append(float(raw))
        except ValueError:
            pass
    return any(v > 0.0 for v in vals)


def _bound_stop(log, rc):
    if rc in (137, -9, 9) or rc < 0:
        return True
    text = log.lower()
    needles = (
        "outofmemoryerror",
        "java heap space",
        "gc overhead",
        "cannot allocate",
        "killed",
    )
    return any(n in text for n in needles)


def classify(log, rc, explore):
    for inv, clause in CLAUSE.items():
        if f"Invariant {inv} is violated" in log:
            return f"FAIL {clause}"
    if _bound_stop(log, rc) or _fingerprint_miss(log):
        return "UNEXPLAINED bound"
    if "Model checking completed. No error has been found." in log and rc == 0:
        if explore or "SCENARIO_DONE" in log:
            return "PASS"
        return "UNEXPLAINED steps"
    err = ""
    for line in log.splitlines():
        if line.startswith("Error:") or "TLC threw" in line:
            err = " ".join(line.split())
            break
    if not err:
        err = "tlc exited " + str(rc)
    if len(err) > 160:
        err = err[:160]
    return "UNEXPLAINED " + err


def run_tlc(workdir):
    cmd = [
        "systemd-run", "--user", "--scope", "-q",
        "-p", "MemoryMax=24G", "-p", "MemorySwapMax=0",
        "java", "-Xmx16G", "-XX:+UseParallelGC",
        "-jar", str(JAR),
        "-workers", "auto", "-deadlock", "-nowarning",
        "-config", "MC.cfg", "MC.tla",
    ]
    log_path = Path(workdir) / "tlc.out"
    with log_path.open("w", encoding="utf-8") as log:
        proc = subprocess.Popen(
            cmd, cwd=workdir, stdout=log, stderr=subprocess.STDOUT, text=True
        )
        rc = proc.wait()
    return rc, log_path.read_text(encoding="utf-8", errors="replace")


def prepare(workdir, spec, mutation, explore):
    path = Path(workdir)
    if path.exists():
        shutil.rmtree(path)
    path.mkdir(parents=True)
    shutil.copy(MODEL / "Journal.tla", path / "Journal.tla")
    (path / "MC.tla").write_text(mc_text(spec, mutation, explore), encoding="utf-8")
    (path / "MC.cfg").write_text(CFG, encoding="utf-8")


def run_id_for(path, mutation, explore):
    if explore:
        return "explore"
    stem = Path(path).stem
    if mutation and mutation != "none":
        return f"{stem}-{mutation}"
    return stem


def execute(spec, mutation, explore, run_id, workroot):
    work = Path(workroot) / run_id
    prepare(work, spec, mutation, explore)
    rc, log = run_tlc(work)
    try:
        events = trace_events(log)
    except ScenarioError as exc:
        line = "UNEXPLAINED " + exc.reason
        if "Invariant " in log:
            line = classify(log, rc, explore)
        outcome_line(line)
        return line
    result = classify(log, rc, explore)
    if events is not None:
        write_observe(events, run_id)
    outcome_line(result)
    return result


def load_normalized(path):
    return normalize(load_scenario(path))


def run_path(path, mutation):
    if mutation not in ("none", "double_vote", "skip_uptodate", "wide_change"):
        outcome_line(f"UNEXPLAINED mutation {mutation}")
        return
    try:
        spec = load_normalized(path)
    except ScenarioError as exc:
        outcome_line("UNEXPLAINED " + exc.reason)
        return
    run_id = run_id_for(path, mutation, False)
    execute(spec, mutation, False, run_id, "/tmp/tupay-f-run")


def run_explore():
    spec = {
        "name": "explore",
        "initial": ["m1", "m2", "m3", "m4"],
        "settle": 0,
        "events": EXPLORE_EVENTS,
        "steps": [],
    }
    execute(spec, "none", True, "explore", "/tmp/tupay-f-run")


def run_mutations():
    files = sorted(SCENARIO_DIR.glob("*.yaml"))
    if not files:
        outcome_line("UNEXPLAINED no shared scenarios")
        return
    for path in files:
        try:
            spec = load_normalized(path)
        except ScenarioError as exc:
            outcome_line(f"{path.stem} UNEXPLAINED {exc.reason}")
            continue
        mutation = MUTATIONS.get(spec["name"] or path.stem)
        if mutation is None:
            outcome_line(f"{path.stem} UNEXPLAINED no mutation")
            continue
        label = spec["name"] or path.stem
        work = f"/tmp/tupay-f-run"
        run_id = f"{path.stem}-{mutation}"
        # Print the scenario name in front of the outcome. A single-file run
        # stays a bare PASS / FAIL / UNEXPLAINED line.
        saved = outcome_line
        def prefixed(line, label=label):
            print(f"{label} {line}", flush=True)
        globals()["outcome_line"] = prefixed
        try:
            execute(spec, mutation, False, run_id, work)
        finally:
            globals()["outcome_line"] = saved


def self_test():
    counts = {"S1": 3, "S2": 2, "S3": 2, "S4": 4, "S5": 3, "S6": 3, "S7": 2, "S8": 3}
    for name, n in counts.items():
        spec = load_normalized(SCENARIO_DIR / f"{name}.yaml")
        assert len(spec["steps"]) == n, (name, len(spec["steps"]))
        assert spec["initial"] == ["m1", "m2", "m3", "m4"]
        assert spec["settle"] == 100 and spec["events"] == 400
    s6 = load_normalized(SCENARIO_DIR / "S6.yaml")
    assert len(s6["steps"][1]["action"]["links"]) == 4
    s2 = mc_text(load_normalized(SCENARIO_DIR / "S2.yaml"), "none", False)
    assert '"coordinator"' in s2 and '"cut"' in s2
    try:
        normalize(load_scenario_text("initial: [m1]\nsteps:\n  - {at: start, do: {restart: crashed}}\nend: {settle: 1}\nbound: {events: 10}\n"))
        raise SystemExit("selector crash was accepted")
    except ScenarioError as exc:
        assert "crashed" in exc.reason
    sample = '''
Error: Invariant J15 is violated.
Error: The behavior up to this point is:
State 1: <Initial predicate>
/\\ x = 0
/\\ obs = <<>>

State 2: <Next>
/\\ obs = << [ event |-> "Elected",
     proc |-> "m1",
     seq |-> 1,
     epoch |-> 1,
     index |-> 0,
     kind |-> "",
     cmd |-> "",
     conf |-> {"m1", "m2"},
     op |-> "",
     target |-> "",
     status |-> "",
     from |-> 0,
     causes |-> <<[proc |-> "m1", seq |-> 0]>>,
     links |-> {} ] >>

State 3: <Next>
/\\ obs = << [ event |-> "Fault",
     proc |-> "env",
     seq |-> 1,
     epoch |-> 0,
     index |-> 0,
     kind |-> "",
     cmd |-> "",
     conf |-> {},
     op |-> "cut",
     target |-> "",
     status |-> "",
     from |-> 0,
     causes |-> <<>>,
     links |-> {<<"m1", "m2">>, <<"m2", "m1">>} ] >>
'''
    events = trace_events(sample)
    assert [e["event"] for e in events] == ["Elected", "Fault"], events
    fault = event_json(events[1], "S2")
    assert fault["links"] == [["m1", "m2"], ["m2", "m1"]]
    assert fault["side"] == "model"
    elected = event_json(events[0], "S2")
    assert elected["config"] == ["m1", "m2"]
    assert elected["causes"] == [{"proc": "m1", "seq": 0}]
    assert classify(sample, 12, False) == "FAIL J1.5"
    ok = "Model checking completed. No error has been found.\nSCENARIO_DONE\n"
    assert classify(ok, 0, False) == "PASS"
    assert classify("Model checking completed. No error has been found.\n", 0, False) == "UNEXPLAINED steps"
    assert classify("Model checking completed. No error has been found.\n", 0, True) == "PASS"
    assert classify("java.lang.OutOfMemoryError: Java heap space\n", 1, False) == "UNEXPLAINED bound"
    assert classify("Model checking completed. No error has been found.\nval = 1.5E-9\nSCENARIO_DONE\n", 0, False) == "UNEXPLAINED bound"
    print("self-test ok")


def load_scenario_text(text):
    return _Doc(_logical_lines(text)).parse()


def main(argv):
    if len(argv) < 2:
        print("usage: run.sh <scenario> | --mutation <id> <scenario> | --mutations | --explore", file=sys.stderr)
        return 2
    if argv[1] == "--self-test":
        self_test()
        return 0
    if argv[1] == "--dump":
        spec = load_normalized(argv[2])
        sys.stdout.write(mc_text(spec, "none", False))
        return 0
    if argv[1] == "--explore":
        run_explore()
        return 0
    if argv[1] == "--mutations":
        run_mutations()
        return 0
    if argv[1] == "--mutation":
        if len(argv) != 4:
            print("usage: run.sh --mutation <id> <scenario>", file=sys.stderr)
            return 2
        run_path(argv[3], argv[2])
        return 0
    if argv[1].startswith("--"):
        print("usage: run.sh <scenario> | --mutation <id> <scenario> | --mutations | --explore", file=sys.stderr)
        return 2
    run_path(argv[1], "none")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except ScenarioError as exc:
        outcome_line("UNEXPLAINED " + exc.reason)
        sys.exit(0)
    except BrokenPipeError:
        sys.exit(0)

#!/usr/bin/env python3
# derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4
"""Compile a scenario to a TLC run and print PASS, FAIL <clause>, or UNEXPLAINED <reason>."""

import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MODEL = ROOT / "model"
JAR = Path.home() / "projects" / "tlaplus" / "tla2tools.jar"
OBSERVE = MODEL / "observe"
SCENARIO_DIR = ROOT / "replay" / "scenarios"

MEMBERS = ("m1", "m2", "m3", "m4", "m5")
SELECTORS = ("coordinator", "follower", "crashed")
# A completing path of every shared scenario needs two elections. One further
# campaign is left so a split vote can retry. Measured election skeleton at
# this epoch cap was about two million states.
MAX_EPOCH = 3
# S8 appends three configuration entries. One spare slot.
MAX_LOG = 4
# One successful catch-up extend, plus retries after a lost reply.
MAX_ROUNDS = 3
# Explore fault counts: no shared scenario exceeds these, and each scenario's
# own faults fit (S8 has three admin steps; S6's cut is four undirected pairs).
EXPLORE_CRASHES = 1
EXPLORE_ADMIN = 3
EXPLORE_LINKS = 4
EXPLORE_EVENTS = 400

MUTATIONS = {
    "S1": "double_vote",
    "S2": "double_vote",
    "S3": "double_vote",
    "S4": "skip_uptodate",
    "S5": "skip_uptodate",
    "S6": "skip_uptodate",
    "S7": "skip_uptodate",
    "S8": "wide_change",
}
CLAUSE = {"J11": "J1.1", "J13": "J1.3", "J15": "J1.5"}
TRIGGER_FIELDS = {"event", "member", "index", "kind", "status", "epoch", "op", "target"}


class ScenarioError(Exception):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


def outcome_line(reason_or_line):
    print(reason_or_line, flush=True)


# ---------- YAML subset ----------

def _strip_comment(line):
    out = []
    quote = False
    esc = False
    for ch in line:
        if quote:
            out.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
            out.append(ch)
        elif ch == "#":
            break
        else:
            out.append(ch)
    return "".join(out).rstrip()


def _flow_depth(text):
    depth = 0
    quote = False
    esc = False
    for ch in text:
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch in "{[":
            depth += 1
        elif ch in "}]":
            depth -= 1
    return depth


def _logical_lines(text):
    raw = []
    for n, line in enumerate(text.splitlines(), 1):
        if line.startswith("---") and n == 1:
            continue
        code = _strip_comment(line)
        if code.strip() == "":
            continue
        if code[:1] == "\t" or "\t" in code[: len(code) - len(code.lstrip(" \t"))]:
            raise ScenarioError("scenario: tab indent")
        indent = len(code) - len(code.lstrip(" "))
        raw.append([indent, code.strip(), n])
    lines = []
    buf = None
    for indent, text, n in raw:
        if buf is None:
            if _flow_depth(text) > 0:
                buf = [indent, text, n]
            else:
                lines.append((indent, text, n))
        else:
            buf[1] += " " + text
            if _flow_depth(buf[1]) <= 0:
                lines.append((buf[0], buf[1], buf[2]))
                buf = None
    if buf is not None:
        raise ScenarioError("scenario: unclosed flow")
    return lines


def _split_key(text):
    quote = False
    esc = False
    for i, ch in enumerate(text):
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch == ":":
            key = text[:i].strip()
            rest = text[i + 1 :].strip()
            if key == "":
                raise ScenarioError("scenario: empty key")
            return key, rest
    raise ScenarioError("scenario: expected key")


class _Flow:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in " \t\r\n":
            self.i += 1

    def parse(self):
        self.skip()
        if self.i >= len(self.s):
            raise ScenarioError("scenario: truncated flow")
        ch = self.s[self.i]
        if ch == "{":
            return self.mapping()
        if ch == "[":
            return self.seq()
        if ch == '"':
            return self.string()
        return self.scalar()

    def mapping(self):
        self.i += 1
        out = {}
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            key = self.key()
            self.skip()
            if self.i >= len(self.s) or self.s[self.i] != ":":
                raise ScenarioError("scenario: flow key")
            self.i += 1
            out[key] = self.parse()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow mapping")

    def key(self):
        self.skip()
        if self.i < len(self.s) and self.s[self.i] == '"':
            return self.string()
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ":},[]":
            self.i += 1
        key = self.s[start:self.i].strip()
        if key == "":
            raise ScenarioError("scenario: empty flow key")
        return key

    def seq(self):
        self.i += 1
        out = []
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow list")

    def string(self):
        self.i += 1
        chars = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == "\\":
                if self.i >= len(self.s):
                    raise ScenarioError("scenario: bad string")
                nxt = self.s[self.i]
                self.i += 1
                chars.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(nxt, nxt))
            elif ch == '"':
                return "".join(chars)
            else:
                chars.append(ch)
        raise ScenarioError("scenario: unclosed string")

    def scalar(self):
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ",}]":
            self.i += 1
        word = self.s[start:self.i].strip()
        if word == "":
            raise ScenarioError("scenario: empty scalar")
        return _scalar(word)


def _scalar(word):
    if word == "true":
        return True
    if word == "false":
        return False
    if word == "null":
        return None
    if re.fullmatch(r"-?\d+", word):
        return int(word)
    return word


def _parse_flow(text):
    parser = _Flow(text)
    value = parser.parse()
    parser.skip()
    if parser.i != len(parser.s):
        raise ScenarioError("scenario: trailing flow")
    return value


class _Doc:
    def __init__(self, lines):
        self.lines = lines
        self.k = 0

    def parse(self):
        if not self.lines:
            raise ScenarioError("scenario: empty file")
        return self._block(0)

    def _block(self, indent):
        if self.k >= len(self.lines):
            return None
        ind, text, _n = self.lines[self.k]
        if ind < indent:
            return None
        if text.startswith("- ") or text == "-":
            return self._list(ind)
        return self._dict(ind)

    def _dict(self, indent):
        out = {}
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind < indent:
                break
            if ind > indent or text.startswith("- ") or text == "-":
                break
            key, rest = _split_key(text)
            if key in out:
                raise ScenarioError(f"scenario: duplicate key {key}")
            self.k += 1
            out[key] = self._value(indent, rest, n)
        return out

    def _list(self, indent):
        items = []
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind != indent or not (text.startswith("- ") or text == "-"):
                break
            rest = text[1:].strip()
            self.k += 1
            if rest == "":
                items.append(self._block(indent + 1))
            elif rest.startswith("{") or rest.startswith("["):
                items.append(_parse_flow(rest))
            elif ":" in rest.split(" ")[0] or (":" in rest and not rest.startswith('"')):
                key, rval = _split_key(rest)
                item = {key: self._value(indent, rval, n)}
                while self.k < len(self.lines):
                    ind2, text2, n2 = self.lines[self.k]
                    if ind2 <= indent or text2.startswith("- ") or text2 == "-":
                        break
                    key2, rest2 = _split_key(text2)
                    self.k += 1
                    item[key2] = self._value(ind2, rest2, n2)
                items.append(item)
            else:
                items.append(_scalar(rest) if not rest.startswith('"') else _parse_flow(rest))
        return items

    def _value(self, indent, rest, _n):
        if rest == "":
            return self._block(indent + 1)
        if rest.startswith("{") or rest.startswith("["):
            return _parse_flow(rest)
        if rest.startswith('"'):
            return _parse_flow(rest)
        return _scalar(rest)


def load_scenario(path):
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        raise ScenarioError(f"scenario file not found") from exc
    doc = _Doc(_logical_lines(text)).parse()
    if not isinstance(doc, dict):
        raise ScenarioError("scenario: expected a mapping")
    return doc


# ---------- scenario to TLA ----------

def _name(value, what):
    if not isinstance(value, str) or value == "":
        raise ScenarioError(f"scenario: {what} needs a member")
    if value not in MEMBERS and value not in SELECTORS:
        raise ScenarioError(f"member {value}")
    return value


def _trigger(at):
    blank = {
        "kind": "event",
        "event": "",
        "member": "",
        "index": -1,
        "ekind": "",
        "status": "",
        "epoch": -1,
        "op": "",
        "target": "",
    }
    if at == "start":
        blank["kind"] = "start"
        return blank
    if not isinstance(at, dict) or "event" not in at:
        raise ScenarioError("scenario: trigger")
    extra = set(at) - TRIGGER_FIELDS
    if extra:
        raise ScenarioError("trigger field " + sorted(extra)[0])
    blank["event"] = str(at["event"])
    if "member" in at:
        blank["member"] = _name(str(at["member"]), "trigger member")
    if "index" in at:
        if not isinstance(at["index"], int):
            raise ScenarioError("scenario: index")
        blank["index"] = at["index"]
    if "kind" in at:
        blank["ekind"] = str(at["kind"])
    if "status" in at:
        blank["status"] = str(at["status"])
    if "epoch" in at:
        if not isinstance(at["epoch"], int):
            raise ScenarioError("scenario: epoch filter")
        blank["epoch"] = at["epoch"]
    if "op" in at:
        blank["op"] = str(at["op"])
    if "target" in at:
        blank["target"] = _name(str(at["target"]), "trigger target")
    return blank


def _action(do):
    if not isinstance(do, dict):
        raise ScenarioError("scenario: action")
    keys = [k for k in do.keys() if k != "at"]
    if len(keys) != 1:
        raise ScenarioError("scenario: action")
    kind = keys[0]
    base = {"kind": kind, "at": "", "target": "", "cmd": "", "links": []}
    if kind in ("add", "remove"):
        base["target"] = _name(str(do[kind]), kind)
        if "at" not in do:
            raise ScenarioError(f"scenario: {kind} needs at")
        base["at"] = _name(str(do["at"]), kind)
    elif kind in ("crash", "restart"):
        base["target"] = _name(str(do[kind]), kind)
    elif kind == "command":
        if not isinstance(do["command"], str) or do["command"] == "":
            raise ScenarioError("scenario: command")
        if "at" not in do:
            raise ScenarioError("scenario: command needs at")
        base["cmd"] = do["command"]
        base["at"] = _name(str(do["at"]), "command")
    elif kind in ("cut", "drop"):
        pairs = do[kind]
        if not isinstance(pairs, list):
            raise ScenarioError(f"scenario: {kind}")
        links = []
        for pair in pairs:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ScenarioError(f"scenario: {kind} pair")
            links.append((_name(str(pair[0]), kind), _name(str(pair[1]), kind)))
        base["links"] = links
    elif kind == "heal":
        pass
    else:
        raise ScenarioError(f"scenario: unknown action {kind}")
    return base


def _uses(action, name):
    if action["at"] == name or action["target"] == name:
        return True
    return any(a == name or b == name for a, b in action["links"])


def normalize(doc):
    if "initial" not in doc or not isinstance(doc["initial"], list) or not doc["initial"]:
        raise ScenarioError("scenario: missing initial")
    initial = []
    for member in doc["initial"]:
        if str(member) not in MEMBERS:
            raise ScenarioError(f"member {member}")
        if str(member) not in initial:
            initial.append(str(member))
    end = doc.get("end")
    bound = doc.get("bound")
    if not isinstance(end, dict) or not isinstance(end.get("settle"), int) or end["settle"] < 0:
        raise ScenarioError("scenario: missing end")
    if not isinstance(bound, dict) or not isinstance(bound.get("events"), int) or bound["events"] < 1:
        raise ScenarioError("scenario: missing bound")
    steps_in = doc.get("steps", [])
    if steps_in is None:
        steps_in = []
    if not isinstance(steps_in, list):
        raise ScenarioError("scenario: steps")
    steps = []
    seen_crash = False
    for raw in steps_in:
        if not isinstance(raw, dict) or "at" not in raw or "do" not in raw:
            raise ScenarioError("scenario: step")
        trig = _trigger(raw["at"])
        act = _action(raw["do"])
        if _uses(act, "crashed") and not seen_crash:
            raise ScenarioError("selector crashed before any crash")
        if trig["kind"] == "start" and _uses(act, "coordinator") and not steps:
            raise ScenarioError("selector coordinator before any election")
        steps.append({"trigger": trig, "action": act})
        if act["kind"] == "crash":
            seen_crash = True
    name = doc.get("scenario", "")
    if not isinstance(name, str):
        name = str(name)
    return {
        "name": name,
        "initial": initial,
        "settle": end["settle"],
        "events": bound["events"],
        "steps": steps,
    }


def tla_str(text):
    esc = text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{esc}"'


def tla_set(items):
    if not items:
        return "{}"
    return "{" + ", ".join(tla_str(x) for x in items) + "}"


def _trig_tla(trig):
    fields = [
        ("kind", tla_str(trig["kind"])),
        ("event", tla_str(trig["event"])),
        ("member", tla_str(trig["member"])),
        ("index", str(trig["index"])),
        ("ekind", tla_str(trig["ekind"])),
        ("status", tla_str(trig["status"])),
        ("epoch", str(trig["epoch"])),
        ("op", tla_str(trig["op"])),
        ("target", tla_str(trig["target"])),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def _act_tla(act):
    if act["links"]:
        body = ", ".join(
            f"<<{tla_str(a)}, {tla_str(b)}>>" for a, b in act["links"]
        )
        links = f"<< {body} >>"
    else:
        links = "<< >>"
    fields = [
        ("kind", tla_str(act["kind"])),
        ("at", tla_str(act["at"])),
        ("target", tla_str(act["target"])),
        ("cmd", tla_str(act["cmd"])),
        ("links", links),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def mc_text(spec, mutation, explore):
    if spec["steps"]:
        parts = []
        for step in spec["steps"]:
            parts.append(
                "  [trigger |->\n" + _trig_tla(step["trigger"])
                + ",\n   action |->\n" + _act_tla(step["action"]) + "]"
            )
        steps = "<<\n" + ",\n".join(parts) + "\n>>"
    else:
        steps = "<< >>"
    crashes = EXPLORE_CRASHES if explore else 0
    admin = EXPLORE_ADMIN if explore else 0
    links = EXPLORE_LINKS if explore else 0
    events = EXPLORE_EVENTS if explore else spec["events"]
    settle = 0 if explore else spec["settle"]
    lines = [
        "---- MODULE MC ----",
        "\\* derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4",
        "EXTENDS Journal",
        "",
        "InitCfg == " + tla_set(spec["initial"]),
        f"MaxEpochC == {MAX_EPOCH}",
        f"MaxLogLenC == {MAX_LOG}",
        f"MaxRoundsC == {MAX_ROUNDS}",
        f"SettleC == {settle}",
        f"MaxEventsC == {events}",
        "MutationC == " + tla_str(mutation),
        "ExploreC == " + ("TRUE" if explore else "FALSE"),
        f"MaxCrashesC == {crashes}",
        f"MaxAdminC == {admin}",
        f"MaxLinkC == {links}",
        'CommandsC == {"c1"}',
        "StepsC == " + steps,
        "====",
        "",
    ]
    return "\n".join(lines)


CFG = """\
SPECIFICATION Spec
INVARIANT J11
INVARIANT J13
INVARIANT J15
CONSTRAINT StateConstraint
CONSTANTS
  InitialConfig <- InitCfg
  MaxEpoch <- MaxEpochC
  MaxLogLen <- MaxLogLenC
  MaxRounds <- MaxRoundsC
  SettleN <- SettleC
  MaxEvents <- MaxEventsC
  Mutation <- MutationC
  Explore <- ExploreC
  MaxCrashes <- MaxCrashesC
  MaxAdmin <- MaxAdminC
  MaxLinkFaults <- MaxLinkC
  Commands <- CommandsC
  Steps <- StepsC
"""


# ---------- TLC values ----------

class _Tla:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in " \t\r\n":
            self.i += 1

    def parse(self):
        self.skip()
        if self.i >= len(self.s):
            raise ValueError("truncated TLA value")
        if self.s.startswith("<<", self.i):
            return self.sequence()
        ch = self.s[self.i]
        if ch == "{":
            return self.set_()
        if ch == "[":
            return self.record()
        if ch == '"':
            return self.string()
        if ch == "-" or ch.isdigit():
            return self.number()
        if ch.isalpha() or ch == "_":
            return self.word()
        raise ValueError("bad TLA value at " + self.s[self.i : self.i + 20])

    def sequence(self):
        self.i += 2
        out = []
        while True:
            self.skip()
            if self.s.startswith(">>", self.i):
                self.i += 2
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def set_(self):
        self.i += 1
        out = []
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def record(self):
        self.i += 1
        out = {}
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            key = self.word() if self.s[self.i].isalpha() or self.s[self.i] == "_" else self.string()
            self.skip()
            if not self.s.startswith("|->", self.i):
                raise ValueError("expected |->")
            self.i += 3
            out[key] = self.parse()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1

    def string(self):
        self.i += 1
        chars = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == "\\":
                if self.i >= len(self.s):
                    raise ValueError("bad string")
                nxt = self.s[self.i]
                self.i += 1
                chars.append('"' if nxt == '"' else nxt)
            elif ch == '"':
                return "".join(chars)
            else:
                chars.append(ch)
        raise ValueError("unclosed string")

    def number(self):
        start = self.i
        if self.s[self.i] == "-":
            self.i += 1
        while self.i < len(self.s) and self.s[self.i].isdigit():
            self.i += 1
        return int(self.s[start:self.i])

    def word(self):
        start = self.i
        while self.i < len(self.s) and (self.s[self.i].isalnum() or self.s[self.i] == "_"):
            self.i += 1
        word = self.s[start:self.i]
        if word == "TRUE":
            return True
        if word == "FALSE":
            return False
        return word


def parse_tla(text):
    parser = _Tla(text)
    value = parser.parse()
    return value


def trace_events(log):
    marker = "The behavior up to this point is:"
    start = log.find(marker)
    if start < 0:
        return None
    body = log[start:]
    heads = list(re.finditer(r"(?m)^State \d+:.*$", body))
    if not heads:
        return None
    events = []
    for i, head in enumerate(heads):
        end = heads[i + 1].start() if i + 1 < len(heads) else len(body)
        chunk = body[head.end():end]
        found = re.search(r"(?m)^/\\ obs =[ \t]*", chunk)
        if not found:
            continue
        try:
            obs = parse_tla(chunk[found.end():])
        except ValueError as exc:
            raise ScenarioError(f"trace parse: {exc}") from exc
        if isinstance(obs, list):
            events.extend(obs)
    return events


def event_json(ev, run):
    name = ev.get("event", "")
    row = {
        "proc": ev.get("proc", ""),
        "seq": ev.get("seq", 0),
        "event": name,
        "causes": [],
        "run": run,
        "side": "model",
    }
    for cause in ev.get("causes") or []:
        if isinstance(cause, dict):
            row["causes"].append({"proc": cause.get("proc", ""), "seq": cause.get("seq", 0)})
    conf = ev.get("conf") or []
    if isinstance(conf, list):
        conf = sorted(str(x) for x in conf)
    if name == "Elected":
        row["epoch"] = ev.get("epoch", 0)
        row["config"] = conf
    elif name == "Appended":
        row["index"] = ev.get("index", 0)
        row["epoch"] = ev.get("epoch", 0)
        row["kind"] = ev.get("kind", "")
        row["payload"] = conf if ev.get("kind") == "config" else ev.get("cmd", "")
    elif name == "Truncated":
        row["from_index"] = ev.get("from", 0)
    elif name == "Committed":
        row["index"] = ev.get("index", 0)
        row["epoch"] = ev.get("epoch", 0)
    elif name == "ConfigInEffect":
        row["index"] = ev.get("index", 0)
        row["config"] = conf
    elif name == "ChangeRequested":
        row["op"] = ev.get("op", "")
        row["target"] = ev.get("target", "")
    elif name == "ChangeReplied":
        row["op"] = ev.get("op", "")
        row["target"] = ev.get("target", "")
        row["status"] = ev.get("status", "")
    elif name == "Fault":
        row["action"] = ev.get("op", "")
        if ev.get("op") in ("cut", "drop"):
            links = []
            for link in ev.get("links") or []:
                if isinstance(link, list) and len(link) == 2:
                    links.append([str(link[0]), str(link[1])])
            row["links"] = sorted(links)
    return row


def write_observe(events, run):
    OBSERVE.mkdir(parents=True, exist_ok=True)
    path = OBSERVE / f"{run}.jsonl"
    lines = [json.dumps(event_json(ev, run), separators=(",", ":"), sort_keys=False) for ev in events]
    path.write_text("\n".join(lines) + ("\n" if lines else ""), encoding="utf-8")
    return path


# ---------- TLC ----------

def _fingerprint_miss(log):
    vals = []
    for raw in re.findall(r"val = ([0-9.eE+-]+)", log):
        try:
            vals.append(float(raw))
        except ValueError:
            pass
    return any(v > 0.0 for v in vals)


def _bound_stop(log, rc):
    if rc in (137, -9, 9) or rc < 0:
        return True
    text = log.lower()
    needles = (
        "outofmemoryerror",
        "java heap space",
        "gc overhead",
        "cannot allocate",
        "killed",
    )
    return any(n in text for n in needles)


def classify(log, rc, explore):
    for inv, clause in CLAUSE.items():
        if f"Invariant {inv} is violated" in log:
            return f"FAIL {clause}"
    if _bound_stop(log, rc) or _fingerprint_miss(log):
        return "UNEXPLAINED bound"
    if "Model checking completed. No error has been found." in log and rc == 0:
        if explore or "SCENARIO_DONE" in log:
            return "PASS"
        return "UNEXPLAINED steps"
    err = ""
    for line in log.splitlines():
        if line.startswith("Error:") or "TLC threw" in line:
            err = " ".join(line.split())
            break
    if not err:
        err = "tlc exited " + str(rc)
    if len(err) > 160:
        err = err[:160]
    return "UNEXPLAINED " + err


def run_tlc(workdir):
    cmd = [
        "systemd-run", "--user", "--scope", "-q",
        "-p", "MemoryMax=24G", "-p", "MemorySwapMax=0",
        "java", "-Xmx16G", "-XX:+UseParallelGC",
        "-jar", str(JAR),
        "-workers", "auto", "-deadlock", "-nowarning",
        "-config", "MC.cfg", "MC.tla",
    ]
    log_path = Path(workdir) / "tlc.out"
    with log_path.open("w", encoding="utf-8") as log:
        proc = subprocess.Popen(
            cmd, cwd=workdir, stdout=log, stderr=subprocess.STDOUT, text=True
        )
        rc = proc.wait()
    return rc, log_path.read_text(encoding="utf-8", errors="replace")


def prepare(workdir, spec, mutation, explore):
    path = Path(workdir)
    if path.exists():
        shutil.rmtree(path)
    path.mkdir(parents=True)
    shutil.copy(MODEL / "Journal.tla", path / "Journal.tla")
    (path / "MC.tla").write_text(mc_text(spec, mutation, explore), encoding="utf-8")
    (path / "MC.cfg").write_text(CFG, encoding="utf-8")


def run_id_for(path, mutation, explore):
    if explore:
        return "explore"
    stem = Path(path).stem
    if mutation and mutation != "none":
        return f"{stem}-{mutation}"
    return stem


def execute(spec, mutation, explore, run_id, workroot):
    work = Path(workroot) / run_id
    prepare(work, spec, mutation, explore)
    rc, log = run_tlc(work)
    try:
        events = trace_events(log)
    except ScenarioError as exc:
        line = "UNEXPLAINED " + exc.reason
        if "Invariant " in log:
            line = classify(log, rc, explore)
        outcome_line(line)
        return line
    result = classify(log, rc, explore)
    if events is not None:
        write_observe(events, run_id)
    outcome_line(result)
    return result


def load_normalized(path):
    return normalize(load_scenario(path))


def run_path(path, mutation):
    if mutation not in ("none", "double_vote", "skip_uptodate", "wide_change"):
        outcome_line(f"UNEXPLAINED mutation {mutation}")
        return
    try:
        spec = load_normalized(path)
    except ScenarioError as exc:
        outcome_line("UNEXPLAINED " + exc.reason)
        return
    run_id = run_id_for(path, mutation, False)
    execute(spec, mutation, False, run_id, "/tmp/tupay-f-run")


def run_explore():
    spec = {
        "name": "explore",
        "initial": ["m1", "m2", "m3", "m4"],
        "settle": 0,
        "events": EXPLORE_EVENTS,
        "steps": [],
    }
    execute(spec, "none", True, "explore", "/tmp/tupay-f-run")


def run_mutations():
    files = sorted(SCENARIO_DIR.glob("*.yaml"))
    if not files:
        outcome_line("UNEXPLAINED no shared scenarios")
        return
    for path in files:
        try:
            spec = load_normalized(path)
        except ScenarioError as exc:
            outcome_line(f"{path.stem} UNEXPLAINED {exc.reason}")
            continue
        mutation = MUTATIONS.get(spec["name"] or path.stem)
        if mutation is None:
            outcome_line(f"{path.stem} UNEXPLAINED no mutation")
            continue
        label = spec["name"] or path.stem
        work = f"/tmp/tupay-f-run"
        run_id = f"{path.stem}-{mutation}"
        # Print the scenario name in front of the outcome. A single-file run
        # stays a bare PASS / FAIL / UNEXPLAINED line.
        saved = outcome_line
        def prefixed(line, label=label):
            print(f"{label} {line}", flush=True)
        globals()["outcome_line"] = prefixed
        try:
            execute(spec, mutation, False, run_id, work)
        finally:
            globals()["outcome_line"] = saved


def self_test():
    counts = {"S1": 3, "S2": 2, "S3": 2, "S4": 4, "S5": 3, "S6": 3, "S7": 2, "S8": 3}
    for name, n in counts.items():
        spec = load_normalized(SCENARIO_DIR / f"{name}.yaml")
        assert len(spec["steps"]) == n, (name, len(spec["steps"]))
        assert spec["initial"] == ["m1", "m2", "m3", "m4"]
        assert spec["settle"] == 100 and spec["events"] == 400
    s6 = load_normalized(SCENARIO_DIR / "S6.yaml")
    assert len(s6["steps"][1]["action"]["links"]) == 4
    s2 = mc_text(load_normalized(SCENARIO_DIR / "S2.yaml"), "none", False)
    assert '"coordinator"' in s2 and '"cut"' in s2
    try:
        normalize(load_scenario_text("initial: [m1]\nsteps:\n  - {at: start, do: {restart: crashed}}\nend: {settle: 1}\nbound: {events: 10}\n"))
        raise SystemExit("selector crash was accepted")
    except ScenarioError as exc:
        assert "crashed" in exc.reason
    sample = '''
Error: Invariant J15 is violated.
Error: The behavior up to this point is:
State 1: <Initial predicate>
/\\ x = 0
/\\ obs = <<>>

State 2: <Next>
/\\ obs = << [ event |-> "Elected",
     proc |-> "m1",
     seq |-> 1,
     epoch |-> 1,
     index |-> 0,
     kind |-> "",
     cmd |-> "",
     conf |-> {"m1", "m2"},
     op |-> "",
     target |-> "",
     status |-> "",
     from |-> 0,
     causes |-> <<[proc |-> "m1", seq |-> 0]>>,
     links |-> {} ] >>

State 3: <Next>
/\\ obs = << [ event |-> "Fault",
     proc |-> "env",
     seq |-> 1,
     epoch |-> 0,
     index |-> 0,
     kind |-> "",
     cmd |-> "",
     conf |-> {},
     op |-> "cut",
     target |-> "",
     status |-> "",
     from |-> 0,
     causes |-> <<>>,
     links |-> {<<"m1", "m2">>, <<"m2", "m1">>} ] >>
'''
    events = trace_events(sample)
    assert [e["event"] for e in events] == ["Elected", "Fault"], events
    fault = event_json(events[1], "S2")
    assert fault["links"] == [["m1", "m2"], ["m2", "m1"]]
    assert fault["side"] == "model"
    elected = event_json(events[0], "S2")
    assert elected["config"] == ["m1", "m2"]
    assert elected["causes"] == [{"proc": "m1", "seq": 0}]
    assert classify(sample, 12, False) == "FAIL J1.5"
    ok = "Model checking completed. No error has been found.\nSCENARIO_DONE\n"
    assert classify(ok, 0, False) == "PASS"
    assert classify("Model checking completed. No error has been found.\n", 0, False) == "UNEXPLAINED steps"
    assert classify("Model checking completed. No error has been found.\n", 0, True) == "PASS"
    assert classify("java.lang.OutOfMemoryError: Java heap space\n", 1, False) == "UNEXPLAINED bound"
    assert classify("Model checking completed. No error has been found.\nval = 1.5E-9\nSCENARIO_DONE\n", 0, False) == "UNEXPLAINED bound"
    print("self-test ok")


def load_scenario_text(text):
    return _Doc(_logical_lines(text)).parse()


def main(argv):
    if len(argv) < 2:
        print("usage: run.sh <scenario> | --mutation <id> <scenario> | --mutations | --explore", file=sys.stderr)
        return 2
    if argv[1] == "--self-test":
        self_test()
        return 0
    if argv[1] == "--dump":
        spec = load_normalized(argv[2])
        sys.stdout.write(mc_text(spec, "none", False))
        return 0
    if argv[1] == "--explore":
        run_explore()
        return 0
    if argv[1] == "--mutations":
        run_mutations()
        return 0
    if argv[1] == "--mutation":
        if len(argv) != 4:
            print("usage: run.sh --mutation <id> <scenario>", file=sys.stderr)
            return 2
        run_path(argv[3], argv[2])
        return 0
    if argv[1].startswith("--"):
        print("usage: run.sh <scenario> | --mutation <id> <scenario> | --mutations | --explore", file=sys.stderr)
        return 2
    run_path(argv[1], "none")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except ScenarioError as exc:
        outcome_line("UNEXPLAINED " + exc.reason)
        sys.exit(0)
    except BrokenPipeError:
        sys.exit(0)

#!/usr/bin/env python3
# derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4
"""Compile a scenario to a TLC run and print PASS, FAIL <clause>, or UNEXPLAINED <reason>."""

import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MODEL = ROOT / "model"
JAR = Path.home() / "projects" / "tlaplus" / "tla2tools.jar"
OBSERVE = MODEL / "observe"
SCENARIO_DIR = ROOT / "replay" / "scenarios"

MEMBERS = ("m1", "m2", "m3", "m4", "m5")
SELECTORS = ("coordinator", "follower", "crashed")
# A completing path of every shared scenario needs two elections. One further
# campaign is left so a split vote can retry. Measured election skeleton at
# this epoch cap was about two million states.
MAX_EPOCH = 3
# S8 appends three configuration entries. One spare slot.
MAX_LOG = 4
# One successful catch-up extend, plus retries after a lost reply.
MAX_ROUNDS = 3
# Explore fault counts: no shared scenario exceeds these, and each scenario's
# own faults fit (S8 has three admin steps; S6's cut is four undirected pairs).
EXPLORE_CRASHES = 1
EXPLORE_ADMIN = 3
EXPLORE_LINKS = 4
EXPLORE_EVENTS = 400

MUTATIONS = {
    "S1": "double_vote",
    "S2": "double_vote",
    "S3": "double_vote",
    "S4": "skip_uptodate",
    "S5": "skip_uptodate",
    "S6": "skip_uptodate",
    "S7": "skip_uptodate",
    "S8": "wide_change",
}
CLAUSE = {"J11": "J1.1", "J13": "J1.3", "J15": "J1.5"}
TRIGGER_FIELDS = {"event", "member", "index", "kind", "status", "epoch", "op", "target"}


class ScenarioError(Exception):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


def outcome_line(reason_or_line):
    print(reason_or_line, flush=True)


# ---------- YAML subset ----------

def _strip_comment(line):
    out = []
    quote = False
    esc = False
    for ch in line:
        if quote:
            out.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
            out.append(ch)
        elif ch == "#":
            break
        else:
            out.append(ch)
    return "".join(out).rstrip()


def _flow_depth(text):
    depth = 0
    quote = False
    esc = False
    for ch in text:
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch in "{[":
            depth += 1
        elif ch in "}]":
            depth -= 1
    return depth


def _logical_lines(text):
    raw = []
    for n, line in enumerate(text.splitlines(), 1):
        if line.startswith("---") and n == 1:
            continue
        code = _strip_comment(line)
        if code.strip() == "":
            continue
        if code[:1] == "\t" or "\t" in code[: len(code) - len(code.lstrip(" \t"))]:
            raise ScenarioError("scenario: tab indent")
        indent = len(code) - len(code.lstrip(" "))
        raw.append([indent, code.strip(), n])
    lines = []
    buf = None
    for indent, text, n in raw:
        if buf is None:
            if _flow_depth(text) > 0:
                buf = [indent, text, n]
            else:
                lines.append((indent, text, n))
        else:
            buf[1] += " " + text
            if _flow_depth(buf[1]) <= 0:
                lines.append((buf[0], buf[1], buf[2]))
                buf = None
    if buf is not None:
        raise ScenarioError("scenario: unclosed flow")
    return lines


def _split_key(text):
    quote = False
    esc = False
    for i, ch in enumerate(text):
        if quote:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                quote = False
            continue
        if ch == '"':
            quote = True
        elif ch == ":":
            key = text[:i].strip()
            rest = text[i + 1 :].strip()
            if key == "":
                raise ScenarioError("scenario: empty key")
            return key, rest
    raise ScenarioError("scenario: expected key")


class _Flow:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in " \t\r\n":
            self.i += 1

    def parse(self):
        self.skip()
        if self.i >= len(self.s):
            raise ScenarioError("scenario: truncated flow")
        ch = self.s[self.i]
        if ch == "{":
            return self.mapping()
        if ch == "[":
            return self.seq()
        if ch == '"':
            return self.string()
        return self.scalar()

    def mapping(self):
        self.i += 1
        out = {}
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            key = self.key()
            self.skip()
            if self.i >= len(self.s) or self.s[self.i] != ":":
                raise ScenarioError("scenario: flow key")
            self.i += 1
            out[key] = self.parse()
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "}":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow mapping")

    def key(self):
        self.skip()
        if self.i < len(self.s) and self.s[self.i] == '"':
            return self.string()
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ":},[]":
            self.i += 1
        key = self.s[start:self.i].strip()
        if key == "":
            raise ScenarioError("scenario: empty flow key")
        return key

    def seq(self):
        self.i += 1
        out = []
        while True:
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            out.append(self.parse())
            self.skip()
            if self.i < len(self.s) and self.s[self.i] == ",":
                self.i += 1
                continue
            if self.i < len(self.s) and self.s[self.i] == "]":
                self.i += 1
                return out
            raise ScenarioError("scenario: flow list")

    def string(self):
        self.i += 1
        chars = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == "\\":
                if self.i >= len(self.s):
                    raise ScenarioError("scenario: bad string")
                nxt = self.s[self.i]
                self.i += 1
                chars.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(nxt, nxt))
            elif ch == '"':
                return "".join(chars)
            else:
                chars.append(ch)
        raise ScenarioError("scenario: unclosed string")

    def scalar(self):
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in ",}]":
            self.i += 1
        word = self.s[start:self.i].strip()
        if word == "":
            raise ScenarioError("scenario: empty scalar")
        return _scalar(word)


def _scalar(word):
    if word == "true":
        return True
    if word == "false":
        return False
    if word == "null":
        return None
    if re.fullmatch(r"-?\d+", word):
        return int(word)
    return word


def _parse_flow(text):
    parser = _Flow(text)
    value = parser.parse()
    parser.skip()
    if parser.i != len(parser.s):
        raise ScenarioError("scenario: trailing flow")
    return value


class _Doc:
    def __init__(self, lines):
        self.lines = lines
        self.k = 0

    def parse(self):
        if not self.lines:
            raise ScenarioError("scenario: empty file")
        return self._block(0)

    def _block(self, indent):
        if self.k >= len(self.lines):
            return None
        ind, text, _n = self.lines[self.k]
        if ind < indent:
            return None
        if text.startswith("- ") or text == "-":
            return self._list(ind)
        return self._dict(ind)

    def _dict(self, indent):
        out = {}
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind < indent:
                break
            if ind > indent or text.startswith("- ") or text == "-":
                break
            key, rest = _split_key(text)
            if key in out:
                raise ScenarioError(f"scenario: duplicate key {key}")
            self.k += 1
            out[key] = self._value(indent, rest, n)
        return out

    def _list(self, indent):
        items = []
        while self.k < len(self.lines):
            ind, text, n = self.lines[self.k]
            if ind != indent or not (text.startswith("- ") or text == "-"):
                break
            rest = text[1:].strip()
            self.k += 1
            if rest == "":
                items.append(self._block(indent + 1))
            elif rest.startswith("{") or rest.startswith("["):
                items.append(_parse_flow(rest))
            elif ":" in rest.split(" ")[0] or (":" in rest and not rest.startswith('"')):
                key, rval = _split_key(rest)
                item = {key: self._value(indent, rval, n)}
                while self.k < len(self.lines):
                    ind2, text2, n2 = self.lines[self.k]
                    if ind2 <= indent or text2.startswith("- ") or text2 == "-":
                        break
                    key2, rest2 = _split_key(text2)
                    self.k += 1
                    item[key2] = self._value(ind2, rest2, n2)
                items.append(item)
            else:
                items.append(_scalar(rest) if not rest.startswith('"') else _parse_flow(rest))
        return items

    def _value(self, indent, rest, _n):
        if rest == "":
            return self._block(indent + 1)
        if rest.startswith("{") or rest.startswith("["):
            return _parse_flow(rest)
        if rest.startswith('"'):
            return _parse_flow(rest)
        return _scalar(rest)


def load_scenario(path):
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        raise ScenarioError(f"scenario file not found") from exc
    doc = _Doc(_logical_lines(text)).parse()
    if not isinstance(doc, dict):
        raise ScenarioError("scenario: expected a mapping")
    return doc


# ---------- scenario to TLA ----------

def _name(value, what):
    if not isinstance(value, str) or value == "":
        raise ScenarioError(f"scenario: {what} needs a member")
    if value not in MEMBERS and value not in SELECTORS:
        raise ScenarioError(f"member {value}")
    return value


def _trigger(at):
    blank = {
        "kind": "event",
        "event": "",
        "member": "",
        "index": -1,
        "ekind": "",
        "status": "",
        "epoch": -1,
        "op": "",
        "target": "",
    }
    if at == "start":
        blank["kind"] = "start"
        return blank
    if not isinstance(at, dict) or "event" not in at:
        raise ScenarioError("scenario: trigger")
    extra = set(at) - TRIGGER_FIELDS
    if extra:
        raise ScenarioError("trigger field " + sorted(extra)[0])
    blank["event"] = str(at["event"])
    if "member" in at:
        blank["member"] = _name(str(at["member"]), "trigger member")
    if "index" in at:
        if not isinstance(at["index"], int):
            raise ScenarioError("scenario: index")
        blank["index"] = at["index"]
    if "kind" in at:
        blank["ekind"] = str(at["kind"])
    if "status" in at:
        blank["status"] = str(at["status"])
    if "epoch" in at:
        if not isinstance(at["epoch"], int):
            raise ScenarioError("scenario: epoch filter")
        blank["epoch"] = at["epoch"]
    if "op" in at:
        blank["op"] = str(at["op"])
    if "target" in at:
        blank["target"] = _name(str(at["target"]), "trigger target")
    return blank


def _action(do):
    if not isinstance(do, dict):
        raise ScenarioError("scenario: action")
    keys = [k for k in do.keys() if k != "at"]
    if len(keys) != 1:
        raise ScenarioError("scenario: action")
    kind = keys[0]
    base = {"kind": kind, "at": "", "target": "", "cmd": "", "links": []}
    if kind in ("add", "remove"):
        base["target"] = _name(str(do[kind]), kind)
        if "at" not in do:
            raise ScenarioError(f"scenario: {kind} needs at")
        base["at"] = _name(str(do["at"]), kind)
    elif kind in ("crash", "restart"):
        base["target"] = _name(str(do[kind]), kind)
    elif kind == "command":
        if not isinstance(do["command"], str) or do["command"] == "":
            raise ScenarioError("scenario: command")
        if "at" not in do:
            raise ScenarioError("scenario: command needs at")
        base["cmd"] = do["command"]
        base["at"] = _name(str(do["at"]), "command")
    elif kind in ("cut", "drop"):
        pairs = do[kind]
        if not isinstance(pairs, list):
            raise ScenarioError(f"scenario: {kind}")
        links = []
        for pair in pairs:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ScenarioError(f"scenario: {kind} pair")
            links.append((_name(str(pair[0]), kind), _name(str(pair[1]), kind)))
        base["links"] = links
    elif kind == "heal":
        pass
    else:
        raise ScenarioError(f"scenario: unknown action {kind}")
    return base


def _uses(action, name):
    if action["at"] == name or action["target"] == name:
        return True
    return any(a == name or b == name for a, b in action["links"])


def normalize(doc):
    if "initial" not in doc or not isinstance(doc["initial"], list) or not doc["initial"]:
        raise ScenarioError("scenario: missing initial")
    initial = []
    for member in doc["initial"]:
        if str(member) not in MEMBERS:
            raise ScenarioError(f"member {member}")
        if str(member) not in initial:
            initial.append(str(member))
    end = doc.get("end")
    bound = doc.get("bound")
    if not isinstance(end, dict) or not isinstance(end.get("settle"), int) or end["settle"] < 0:
        raise ScenarioError("scenario: missing end")
    if not isinstance(bound, dict) or not isinstance(bound.get("events"), int) or bound["events"] < 1:
        raise ScenarioError("scenario: missing bound")
    steps_in = doc.get("steps", [])
    if steps_in is None:
        steps_in = []
    if not isinstance(steps_in, list):
        raise ScenarioError("scenario: steps")
    steps = []
    seen_crash = False
    for raw in steps_in:
        if not isinstance(raw, dict) or "at" not in raw or "do" not in raw:
            raise ScenarioError("scenario: step")
        trig = _trigger(raw["at"])
        act = _action(raw["do"])
        if _uses(act, "crashed") and not seen_crash:
            raise ScenarioError("selector crashed before any crash")
        if trig["kind"] == "start" and _uses(act, "coordinator") and not steps:
            raise ScenarioError("selector coordinator before any election")
        steps.append({"trigger": trig, "action": act})
        if act["kind"] == "crash":
            seen_crash = True
    name = doc.get("scenario", "")
    if not isinstance(name, str):
        name = str(name)
    return {
        "name": name,
        "initial": initial,
        "settle": end["settle"],
        "events": bound["events"],
        "steps": steps,
    }


def tla_str(text):
    esc = text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{esc}"'


def tla_set(items):
    if not items:
        return "{}"
    return "{" + ", ".join(tla_str(x) for x in items) + "}"


def _trig_tla(trig):
    fields = [
        ("kind", tla_str(trig["kind"])),
        ("event", tla_str(trig["event"])),
        ("member", tla_str(trig["member"])),
        ("index", str(trig["index"])),
        ("ekind", tla_str(trig["ekind"])),
        ("status", tla_str(trig["status"])),
        ("epoch", str(trig["epoch"])),
        ("op", tla_str(trig["op"])),
        ("target", tla_str(trig["target"])),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def _act_tla(act):
    if act["links"]:
        body = ", ".join(
            f"<<{tla_str(a)}, {tla_str(b)}>>" for a, b in act["links"]
        )
        links = f"<< {body} >>"
    else:
        links = "<< >>"
    fields = [
        ("kind", tla_str(act["kind"])),
        ("at", tla_str(act["at"])),
        ("target", tla_str(act["target"])),
        ("cmd", tla_str(act["cmd"])),
        ("links", links),
    ]
    body = ",\n".join(f"     {name} |-> {value}" for name, value in fields)
    return "    [" + body[5:] + "]"


def mc_text(spec, mutation, explore):
    if spec["steps"]:
        parts = []
        for step in spec["steps"]:
            parts.append(
                "  [trigger |->\n" + _trig_tla(step["trigger"])
                + ",\n   action |->\n" + _act_tla(step["action"]) + "]"
            )
        steps = "<<\n" + ",\n".join(parts) + "\n>>"
    else:
        steps = "<< >>"
    crashes = EXPLORE_CRASHES if explore else 0
    admin = EXPLORE_ADMIN if explore else 0
    links = EXPLORE_LINKS if explore else 0
    events = EXPLORE_EVENTS if explore else spec["events"]
    settle = 0 if explore else spec["settle"]
    lines = [
        "---- MODULE MC ----",
        "\\* derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4",
        "EXTENDS Journal",
        "",
        "InitCfg == " + tla_set(spec["initial"]),
        f"MaxEpochC == {MAX_EPOCH}",
        f"MaxLogLenC == {MAX_LOG}",
        f"MaxRoundsC == {MAX_ROUNDS}",
        f"SettleC == {settle}",
        f"MaxEventsC == {events}",
        "MutationC == " + tla_str(mutation),
        "ExploreC == " + ("TRUE" if explore else "FALSE"),
        f"MaxCrashesC == {crashes}",
        f"MaxAdminC == {admin}",
        f"MaxLinkC == {links}",
        'CommandsC == {"c1"}',
        "StepsC == " + steps,
        "====",
        "",
    ]
    return "\n".join(lines)


